@Test
public void testEnableDelayedDeliveryMessages() throws Exception {
    admin.namespaces().createNamespace("delayed-delivery-messages/default-enable-service-conf");
    String namespace = "delayed-delivery-messages/default-enable-service-conf";
    String topicName = "persistent://delayed-delivery-messages/default-enable-service-conf/test";
    assertTrue(admin.namespaces().getDelayedDelivery(namespace).isActive());
    @Cleanup
    Consumer<String> consumer = pulsarClient.newConsumer(Schema.STRING).topic(topicName).subscriptionName("test-sub").subscriptionType(SubscriptionType.Shared).subscribe();
    @Cleanup
    Producer<String> producer = pulsarClient.newProducer(Schema.STRING).topic(topicName).create();
    for (int i = 0; i < 10; i++) {
        producer.newMessage().value("delayed-msg-" + i).deliverAfter(5, TimeUnit.SECONDS).sendAsync();
    }
    producer.flush();
    // Delayed messages might not come in same exact order
    Set<String> delayedMessages = new TreeSet<>();
    for (int i = 0; i < 10; i++) {
        Message<String> msg = consumer.receive(10, TimeUnit.SECONDS);
        delayedMessages.add(msg.getValue());
        consumer.acknowledge(msg);
    }
    for (int i = 0; i < 10; i++) {
        assertTrue(delayedMessages.contains("delayed-msg-" + i));
    }
}

@Test
public void testGetLastMessageId() throws Exception {
    try {
        persistentTopics.getLastMessageId(testTenant, testNamespace, "my-topic", true);
    } catch (Exception e) {
        //System.out.println(e.getMessage());
        Assert.assertEquals("Topic not found", e.getMessage());
    }
    String key = "legendtkl";
    final String topicName = "persistent://prop/ns-abc/my-topic";
    final String messagePredicate = "my-message-" + key + "-";
    final int numberOfMessages = 30;
    // 2. Create Producer
    Producer<byte[]> producer = pulsarClient.newProducer().topic(topicName).enableBatching(false).messageRoutingMode(MessageRoutingMode.SinglePartition).create();
    // 3. Publish message and get message id
    for (int i = 0; i < numberOfMessages; i++) {
        String message = messagePredicate + i;
        producer.send(message.getBytes());
    }
    MessageId id = persistentTopics.getLastMessageId("prop", "ns-abc", "my-topic", true);
    System.out.println(id.toString());
    Assert.assertTrue(((MessageIdImpl) id).getLedgerId() >= 0);
    Assert.assertEquals(numberOfMessages - 1, ((MessageIdImpl) id).getEntryId());
    // send more numberOfMessages messages, the last message id should be numberOfMessages*2-1
    for (int i = 0; i < numberOfMessages; i++) {
        String message = messagePredicate + i;
        producer.send(message.getBytes());
    }
    id = persistentTopics.getLastMessageId("prop", "ns-abc", "my-topic", true);
    System.out.println(id.toString());
    Assert.assertTrue(((MessageIdImpl) id).getLedgerId() > 0);
    Assert.assertEquals(2 * numberOfMessages - 1, ((MessageIdImpl) id).getEntryId());
    System.out.println(id.toString());
}

