    // Create producer
    Producer<byte[]> producer1 = pulsarClient.newProducer(Schema.BYTES).topic("persistent://prop-xyz/ns1-bundles/ds1").enableBatching(false).messageRoutingMode(MessageRoutingMode.SinglePartition).create();
