@Test
public void testSubscribeRate() throws Exception {
    SubscribeRate subscribeRate = new SubscribeRate(1, 5);
    String namespace = "my-tenants/my-namespace";
    admin.tenants().createTenant("my-tenants", new TenantInfo(Sets.newHashSet(), Sets.newHashSet(testLocalCluster)));
    admin.namespaces().createNamespace(namespace, Sets.newHashSet(testLocalCluster));
    admin.namespaces().setSubscribeRate(namespace, subscribeRate);
    assertEquals(subscribeRate, admin.namespaces().getSubscribeRate(namespace));
    String topicName = "persistent://" + namespace + "/" + "subscribe-rate";
    admin.topics().createPartitionedTopic(topicName, 2);
    pulsar.getConfiguration().setAuthorizationEnabled(false);
    Consumer<?> consumer = pulsarClient.newConsumer().topic(topicName).subscriptionType(SubscriptionType.Shared).subscriptionName("subscribe-rate").subscribe();
    assertTrue(consumer.isConnected());
    // Subscribe Rate Limiter is enabled, will limited by broker
    pulsarClient.updateServiceUrl(lookupUrl.toString());
    Thread.sleep(1000L);
    assertFalse(consumer.isConnected());
    // Out of limit period
    Thread.sleep(6000L);
    pulsarClient.updateServiceUrl(lookupUrl.toString());
    assertTrue(consumer.isConnected());
    // Disable Subscribe Rate Limiter
    subscribeRate = new SubscribeRate(0, 10);
    admin.namespaces().setSubscribeRate(namespace, subscribeRate);
    pulsarClient.updateServiceUrl(lookupUrl.toString());
    Thread.sleep(1000L);
    assertTrue(consumer.isConnected());
    pulsar.getConfiguration().setAuthorizationEnabled(true);
    admin.topics().deletePartitionedTopic(topicName, true);
    admin.namespaces().deleteNamespace(namespace);
    admin.tenants().deleteTenant("my-tenants");
}

@Test
public void testSetOffloadThreshold() throws Exception {
    TopicName topicName = TopicName.get("persistent", this.testTenant, "offload", "offload-topic");
    String namespace = topicName.getNamespaceObject().toString();
    System.out.println(namespace);
    // set a default
    pulsar.getConfiguration().setManagedLedgerOffloadAutoTriggerSizeThresholdBytes(1);
    // create the namespace
    admin.namespaces().createNamespace(namespace, Sets.newHashSet(testLocalCluster));
    admin.topics().createNonPartitionedTopic(topicName.toString());
    // assert we get the default which indicates it will fall back to default
    assertEquals(-1, admin.namespaces().getOffloadThreshold(namespace));
    // the ledger config should have the expected value
    ManagedLedgerConfig ledgerConf = pulsar.getBrokerService().getManagedLedgerConfig(topicName).get();
    assertEquals(ledgerConf.getOffloadAutoTriggerSizeThresholdBytes(), 1);
    // set an override for the namespace
    admin.namespaces().setOffloadThreshold(namespace, 100);
    assertEquals(100, admin.namespaces().getOffloadThreshold(namespace));
    ledgerConf = pulsar.getBrokerService().getManagedLedgerConfig(topicName).get();
    assertEquals(ledgerConf.getOffloadAutoTriggerSizeThresholdBytes(), 100);
    // set another negative value to disable
    admin.namespaces().setOffloadThreshold(namespace, -2);
    assertEquals(-2, admin.namespaces().getOffloadThreshold(namespace));
    ledgerConf = pulsar.getBrokerService().getManagedLedgerConfig(topicName).get();
    assertEquals(ledgerConf.getOffloadAutoTriggerSizeThresholdBytes(), -2);
    // set back to -1 and fall back to default
    admin.namespaces().setOffloadThreshold(namespace, -1);
    assertEquals(-1, admin.namespaces().getOffloadThreshold(namespace));
    ledgerConf = pulsar.getBrokerService().getManagedLedgerConfig(topicName).get();
    assertEquals(ledgerConf.getOffloadAutoTriggerSizeThresholdBytes(), 1);
    // cleanup
    admin.topics().delete(topicName.toString(), true);
    admin.namespaces().deleteNamespace(namespace);
}

@Test
public void testGetSubscriptions() {
    String testLocalTopicName = "topic-not-found";
    // 1) Confirm that the topic does not exist
    AsyncResponse response = mock(AsyncResponse.class);
    persistentTopics.getSubscriptions(response, testTenant, testNamespace, testLocalTopicName, true);
    ArgumentCaptor<RestException> errorCaptor = ArgumentCaptor.forClass(RestException.class);
    verify(response, timeout(5000).times(1)).resume(errorCaptor.capture());
    Assert.assertEquals(errorCaptor.getValue().getResponse().getStatus(), Response.Status.NOT_FOUND.getStatusCode());
    Assert.assertEquals(errorCaptor.getValue().getMessage(), "Topic not found");
    // 2) Confirm that the partitioned topic does not exist
    response = mock(AsyncResponse.class);
    persistentTopics.getSubscriptions(response, testTenant, testNamespace, testLocalTopicName + "-partition-0", true);
    errorCaptor = ArgumentCaptor.forClass(RestException.class);
    verify(response, timeout(5000).times(1)).resume(errorCaptor.capture());
    Assert.assertEquals(errorCaptor.getValue().getResponse().getStatus(), Response.Status.NOT_FOUND.getStatusCode());
    Assert.assertEquals(errorCaptor.getValue().getMessage(), "Partitioned Topic not found: persistent://my-tenant/my-namespace/topic-not-found-partition-0 has zero partitions");
    // 3) Create the partitioned topic
    persistentTopics.createPartitionedTopic(testTenant, testNamespace, testLocalTopicName, 3);
    // 4) Create a subscription
    response = mock(AsyncResponse.class);
    persistentTopics.createSubscription(response, testTenant, testNamespace, testLocalTopicName, "test", true, (MessageIdImpl) MessageId.earliest, false);
    ArgumentCaptor<Response> responseCaptor = ArgumentCaptor.forClass(Response.class);
    verify(response, timeout(5000).times(1)).resume(responseCaptor.capture());
    Assert.assertEquals(responseCaptor.getValue().getStatus(), Response.Status.NO_CONTENT.getStatusCode());
    // 5) Confirm that the subscription exists
    response = mock(AsyncResponse.class);
    persistentTopics.getSubscriptions(response, testTenant, testNamespace, testLocalTopicName + "-partition-0", true);
    verify(response, timeout(5000).times(1)).resume(Lists.newArrayList("test"));
    // 6) Delete the subscription
    response = mock(AsyncResponse.class);
    persistentTopics.deleteSubscription(response, testTenant, testNamespace, testLocalTopicName, "test", true);
    responseCaptor = ArgumentCaptor.forClass(Response.class);
    verify(response, timeout(5000).times(1)).resume(responseCaptor.capture());
    Assert.assertEquals(responseCaptor.getValue().getStatus(), Response.Status.NO_CONTENT.getStatusCode());
    // 7) Confirm that the subscription does not exist
    response = mock(AsyncResponse.class);
    persistentTopics.getSubscriptions(response, testTenant, testNamespace, testLocalTopicName + "-partition-0", true);
    verify(response, timeout(5000).times(1)).resume(Lists.newArrayList());
    // 8) Delete the partitioned topic
    response = mock(AsyncResponse.class);
    persistentTopics.deletePartitionedTopic(response, testTenant, testNamespace, testLocalTopicName, true, true);
    responseCaptor = ArgumentCaptor.forClass(Response.class);
    verify(response, timeout(5000).times(1)).resume(responseCaptor.capture());
    Assert.assertEquals(responseCaptor.getValue().getStatus(), Response.Status.NO_CONTENT.getStatusCode());
}

