    producer.close();
    admin.namespaces().unload("prop/ns-test-1");
    countDownLatch.await();
    Assert.assertTrue(onLoad.get());
    Assert.assertTrue(unLoad.get());
    admin.topics().delete(topic);
    admin.namespaces().deleteNamespace(namespace);
}

