/**
 * make sure new schema is backwards compatible with latest
 */
@Test
public void testBackwardCompatibility() {
    SchemaCompatibilityCheck schemaCompatibilityCheck = getSchemaCheck();
    // adding a field with default is backwards compatible
    Assert.assertTrue(schemaCompatibilityCheck.isCompatible(schemaData1, schemaData2, SchemaCompatibilityStrategy.BACKWARD), "adding a field with default is backwards compatible");
    // adding a field without default is NOT backwards compatible
    Assert.assertFalse(schemaCompatibilityCheck.isCompatible(schemaData1, schemaData3, SchemaCompatibilityStrategy.BACKWARD), "adding a field without default is NOT backwards compatible");
    // Modifying a field name with an alias is backwards compatible
    Assert.assertTrue(schemaCompatibilityCheck.isCompatible(schemaData1, schemaData4, SchemaCompatibilityStrategy.BACKWARD), "Modifying a field name with an alias is backwards compatible");
    // evolving field to a union is backwards compatible
    Assert.assertTrue(schemaCompatibilityCheck.isCompatible(schemaData1, schemaData5, SchemaCompatibilityStrategy.BACKWARD), "evolving field to a union is backwards compatible");
    // removing a field from a union is NOT backwards compatible
    Assert.assertFalse(schemaCompatibilityCheck.isCompatible(schemaData5, schemaData1, SchemaCompatibilityStrategy.BACKWARD), "removing a field from a union is NOT backwards compatible");
    // adding a field to a union is backwards compatible
    Assert.assertTrue(schemaCompatibilityCheck.isCompatible(schemaData5, schemaData6, SchemaCompatibilityStrategy.BACKWARD), "adding a field to a union is backwards compatible");
    // removing a field a union is NOT backwards compatible
    Assert.assertFalse(schemaCompatibilityCheck.isCompatible(schemaData6, schemaData5, SchemaCompatibilityStrategy.BACKWARD), "removing a field a union is NOT backwards compatible");
}

/**
 * Check to make sure the last schema version is forward-compatible with new schemas
 */
@Test
public void testForwardCompatibility() {
    SchemaCompatibilityCheck schemaCompatibilityCheck = getSchemaCheck();
    Assert.assertTrue(schemaCompatibilityCheck.isCompatible(schemaData1, schemaData2, SchemaCompatibilityStrategy.FORWARD), "adding a field is forward compatible");
    Assert.assertTrue(schemaCompatibilityCheck.isCompatible(schemaData1, schemaData3, SchemaCompatibilityStrategy.FORWARD), "adding a field is forward compatible");
    Assert.assertTrue(schemaCompatibilityCheck.isCompatible(schemaData2, schemaData3, SchemaCompatibilityStrategy.FORWARD), "adding a field is forward compatible");
    Assert.assertTrue(schemaCompatibilityCheck.isCompatible(schemaData3, schemaData2, SchemaCompatibilityStrategy.FORWARD), "adding a field is forward compatible");
    Assert.assertTrue(schemaCompatibilityCheck.isCompatible(schemaData3, schemaData2, SchemaCompatibilityStrategy.FORWARD), "adding a field is forward compatible");
    Assert.assertTrue(schemaCompatibilityCheck.isCompatible(schemaData2, schemaData7, SchemaCompatibilityStrategy.FORWARD), "removing fields is forward compatible");
    Assert.assertTrue(schemaCompatibilityCheck.isCompatible(schemaData2, schemaData1, SchemaCompatibilityStrategy.FORWARD), "removing fields with defaults forward compatible");
}

/**
 * Make sure the new schema is forward- and backward-compatible from the latest to newest and from the newest to latest.
 */
@Test
public void testFullCompatibility() {
