@Test
public void testJvmDirectMemoryUsedMetric() throws Exception {
    PooledByteBufAllocator allocator = new //
    PooledByteBufAllocator(// preferDirect
    true, // nHeapArenas,
    0, // nDirectArena
    1, // pageSize
    8192, // maxOrder
    11, // tinyCacheSize
    64, // smallCacheSize
    32, // normalCacheSize
    8, // Cache all threads
    true);
    int allocateMemory = 17777216;
    long directMemory1 = JvmMetrics.getJvmDirectMemoryUsed();
    ByteBuf buf2 = allocator.directBuffer(allocateMemory, allocateMemory);
    long directMemory2 = JvmMetrics.getJvmDirectMemoryUsed();
    assertEquals(directMemory2, directMemory1 + allocateMemory);
    ByteBuf buf3 = allocator.directBuffer(allocateMemory, allocateMemory);
    long directMemory3 = JvmMetrics.getJvmDirectMemoryUsed();
    assertEquals(directMemory3, directMemory2 + allocateMemory);
    buf3.release();
    directMemory3 = JvmMetrics.getJvmDirectMemoryUsed();
    assertEquals(directMemory3, directMemory2);
    buf2.release();
    directMemory2 = JvmMetrics.getJvmDirectMemoryUsed();
    assertEquals(directMemory2, directMemory1);
}

@Test
public void testConsumerStatsOnZeroMaxUnackedMessagesPerConsumer() throws PulsarClientException, InterruptedException, PulsarAdminException {
    Assert.assertEquals(pulsar.getConfiguration().getMaxUnackedMessagesPerConsumer(), 0);
    final String topicName = "persistent://my-property/my-ns/testConsumerStatsOnZeroMaxUnackedMessagesPerConsumer";
    Consumer<byte[]> consumer = pulsarClient.newConsumer().topic(topicName).subscriptionType(SubscriptionType.Shared).ackTimeout(1, TimeUnit.SECONDS).subscriptionName("sub").subscribe();
    Producer<byte[]> producer = pulsarClient.newProducer().topic(topicName).create();
    final int messages = 10;
    for (int i = 0; i < messages; i++) {
        producer.send(("message-" + i).getBytes());
    }
    int received = 0;
    for (int i = 0; i < messages; i++) {
        // don't ack messages here
        consumer.receive();
        received++;
    }
    Assert.assertEquals(received, messages);
    received = 0;
    TopicStats stats = admin.topics().getStats(topicName);
    Assert.assertEquals(stats.subscriptions.size(), 1);
    Assert.assertEquals(stats.subscriptions.entrySet().iterator().next().getValue().consumers.size(), 1);
    Assert.assertFalse(stats.subscriptions.entrySet().iterator().next().getValue().consumers.get(0).blockedConsumerOnUnackedMsgs);
    Assert.assertEquals(stats.subscriptions.entrySet().iterator().next().getValue().consumers.get(0).unackedMessages, messages);
    for (int i = 0; i < messages; i++) {
        consumer.acknowledge(consumer.receive());
        received++;
    }
    Assert.assertEquals(received, messages);
    // wait acknowledge send
    Thread.sleep(2000);
    stats = admin.topics().getStats(topicName);
    Assert.assertFalse(stats.subscriptions.entrySet().iterator().next().getValue().consumers.get(0).blockedConsumerOnUnackedMsgs);
    Assert.assertEquals(stats.subscriptions.entrySet().iterator().next().getValue().consumers.get(0).unackedMessages, 0);
}

