/**
 * It verifies that redelivered messages are sorted based on the ledger-ids.
 * <pre>
 * 1. client publishes 100 messages across 50 ledgers
 * 2. broker delivers 100 messages to consumer
 * 3. consumer ack every alternative message and doesn't ack 50 messages
 * 4. broker sorts replay messages based on ledger and redelivers messages ledger by ledger
 * </pre>
 * @throws Exception
 */
@Test
public void testOrderedRedelivery() throws Exception {
    String topic = "persistent://my-property/my-ns/redelivery-" + System.currentTimeMillis();
    conf.setManagedLedgerMaxEntriesPerLedger(2);
    conf.setManagedLedgerMinLedgerRolloverTimeMinutes(0);
    @Cleanup
    Producer<byte[]> producer = pulsarClient.newProducer().topic(topic).producerName("my-producer-name").create();
    ConsumerBuilder<byte[]> consumerBuilder = pulsarClient.newConsumer().topic(topic).subscriptionName("s1").subscriptionType(SubscriptionType.Shared);
    ConsumerImpl<byte[]> consumer1 = (ConsumerImpl<byte[]>) consumerBuilder.subscribe();
    final int totalMsgs = 100;
    for (int i = 0; i < totalMsgs; i++) {
        String message = "my-message-" + i;
        producer.send(message.getBytes());
    }
    int consumedCount = 0;
    Set<MessageId> messageIds = Sets.newHashSet();
    for (int i = 0; i < totalMsgs; i++) {
        Message<byte[]> message = consumer1.receive(5, TimeUnit.SECONDS);
        if (message != null && (consumedCount % 2) == 0) {
            consumer1.acknowledge(message);
        } else {
            messageIds.add(message.getMessageId());
        }
        consumedCount += 1;
    }
    assertEquals(totalMsgs, consumedCount);
    // redeliver all unack messages
    consumer1.redeliverUnacknowledgedMessages(messageIds);
    MessageIdImpl lastMsgId = null;
    for (int i = 0; i < totalMsgs / 2; i++) {
        Message<byte[]> message = consumer1.receive(5, TimeUnit.SECONDS);
        MessageIdImpl msgId = (MessageIdImpl) message.getMessageId();
        if (lastMsgId != null) {
            assertTrue(lastMsgId.getLedgerId() <= msgId.getLedgerId(), "lastMsgId: " + lastMsgId + " -- msgId: " + msgId);
        }
        lastMsgId = msgId;
    }
    // close consumer so, this consumer's unack messages will be redelivered to new consumer
    consumer1.close();
    @Cleanup
    Consumer<byte[]> consumer2 = consumerBuilder.subscribe();
    lastMsgId = null;
    for (int i = 0; i < totalMsgs / 2; i++) {
        Message<byte[]> message = consumer2.receive(5, TimeUnit.SECONDS);
        MessageIdImpl msgId = (MessageIdImpl) message.getMessageId();
        if (lastMsgId != null) {
            assertTrue(lastMsgId.getLedgerId() <= msgId.getLedgerId());
        }
        lastMsgId = msgId;
    }
}

@Test
public void testUnAckMessageRedeliveryWithReceiveAsync() throws PulsarClientException, ExecutionException, InterruptedException {
    String topic = "persistent://my-property/my-ns/async-unack-redelivery";
    Consumer<String> consumer = pulsarClient.newConsumer(Schema.STRING).topic(topic).subscriptionName("s1").ackTimeout(3, TimeUnit.SECONDS).subscribe();
    Producer<String> producer = pulsarClient.newProducer(Schema.STRING).topic(topic).enableBatching(true).batchingMaxMessages(5).batchingMaxPublishDelay(1, TimeUnit.SECONDS).create();
    final int messages = 10;
    List<CompletableFuture<Message<String>>> futures = new ArrayList<>(10);
    for (int i = 0; i < messages; i++) {
        futures.add(consumer.receiveAsync());
    }
    for (int i = 0; i < messages; i++) {
        producer.sendAsync("my-message-" + i);
    }
    int messageReceived = 0;
    for (CompletableFuture<Message<String>> future : futures) {
        Message<String> message = future.get();
        assertNotNull(message);
        messageReceived++;
        // Don't ack message, wait for ack timeout.
    }
    assertEquals(10, messageReceived);
    for (int i = 0; i < messages; i++) {
        Message<String> message = consumer.receive();
        assertNotNull(message);
        messageReceived++;
        consumer.acknowledge(message);
    }
    assertEquals(20, messageReceived);
    producer.close();
    consumer.close();
}

@Test
public void testDeadLetterTopic() throws Exception {
    final String topic = "persistent://my-property/my-ns/dead-letter-topic";
    final int maxRedeliveryCount = 2;
    final int sendMessages = 100;
    Consumer<byte[]> consumer = pulsarClient.newConsumer(Schema.BYTES).topic(topic).subscriptionName("my-subscription").subscriptionType(SubscriptionType.Shared).ackTimeout(1, TimeUnit.SECONDS).deadLetterPolicy(DeadLetterPolicy.builder().maxRedeliverCount(maxRedeliveryCount).build()).receiverQueueSize(100).subscriptionInitialPosition(SubscriptionInitialPosition.Earliest).subscribe();
    // Creates new client connection
    PulsarClient newPulsarClient = newPulsarClient(lookupUrl.toString(), 0);
    Consumer<byte[]> deadLetterConsumer = newPulsarClient.newConsumer(Schema.BYTES).topic("persistent://my-property/my-ns/dead-letter-topic-my-subscription-DLQ").subscriptionName("my-subscription").subscriptionInitialPosition(SubscriptionInitialPosition.Earliest).subscribe();
    Producer<byte[]> producer = pulsarClient.newProducer(Schema.BYTES).topic(topic).create();
    for (int i = 0; i < sendMessages; i++) {
        producer.send(String.format("Hello Pulsar [%d]", i).getBytes());
    }
    producer.close();
    int totalReceived = 0;
    do {
        Message<byte[]> message = consumer.receive();
        log.info("consumer received message : {} {}", message.getMessageId(), new String(message.getData()));
        totalReceived++;
    } while (totalReceived < sendMessages * (maxRedeliveryCount + 1));
    int totalInDeadLetter = 0;
    do {
        Message message = deadLetterConsumer.receive();
        log.info("dead letter consumer received message : {} {}", message.getMessageId(), new String(message.getData()));
        deadLetterConsumer.acknowledge(message);
        totalInDeadLetter++;
    } while (totalInDeadLetter < sendMessages);
    deadLetterConsumer.close();
    consumer.close();
    Consumer<byte[]> checkConsumer = this.pulsarClient.newConsumer(Schema.BYTES).topic(topic).subscriptionName("my-subscription").subscriptionType(SubscriptionType.Shared).subscriptionInitialPosition(SubscriptionInitialPosition.Earliest).subscribe();
    Message<byte[]> checkMessage = checkConsumer.receive(3, TimeUnit.SECONDS);
    if (checkMessage != null) {
        log.info("check consumer received message : {} {}", checkMessage.getMessageId(), new String(checkMessage.getData()));
    }
    assertNull(checkMessage);
    checkConsumer.close();
    newPulsarClient.close();
}

