        stats = topicRef.getStats();
        subStats = stats.subscriptions.values().iterator().next();
        // subscription stats
        assertEquals(stats.subscriptions.keySet().size(), 1);
        assertEquals(subStats.msgBacklog, 0);
        assertEquals(subStats.consumers.size(), 1);
