@Test
public void testProducerInterceptor() throws PulsarClientException {
    Map<MessageId, List<String>> ackCallback = new HashMap<>();
    abstract class BaseInterceptor implements org.apache.pulsar.client.api.interceptor.ProducerInterceptor {

        private static final String set = "set";

        private String tag;

        private BaseInterceptor(String tag) {
            this.tag = tag;
        }

        @Override
        public void close() {
        }

        @Override
        public Message beforeSend(Producer producer, Message message) {
            MessageImpl msg = (MessageImpl) message;
            msg.getMessageBuilder().addProperties(KeyValue.newBuilder().setKey(tag).setValue(set));
            return message;
        }

        @Override
        public void onSendAcknowledgement(Producer producer, Message message, MessageId msgId, Throwable exception) {
            if (!set.equals(message.getProperties().get(tag))) {
                return;
            }
            ackCallback.computeIfAbsent(msgId, k -> new ArrayList<>()).add(tag);
        }
    }
    BaseInterceptor interceptor1 = new BaseInterceptor("int1") {

        @Override
        public boolean eligible(Message message) {
            return true;
        }
    };
    BaseInterceptor interceptor2 = new BaseInterceptor("int2") {

        @Override
        public boolean eligible(Message message) {
            return SchemaType.STRING.equals(((MessageImpl) message).getSchema().getSchemaInfo().getType());
        }
    };
    BaseInterceptor interceptor3 = new BaseInterceptor("int3") {

        @Override
        public boolean eligible(Message message) {
            return SchemaType.INT32.equals(((MessageImpl) message).getSchema().getSchemaInfo().getType());
        }
    };
    Producer<String> producer = pulsarClient.newProducer(Schema.STRING).topic("persistent://my-property/my-ns/my-topic").intercept(interceptor1, interceptor2, interceptor3).create();
    MessageId messageId = producer.newMessage().property("STR", "Y").value("Hello Pulsar!").send();
    Assert.assertEquals(ackCallback.get(messageId), Arrays.asList(interceptor1.tag, interceptor2.tag));
    log.info("Send result messageId: {}", messageId);
    MessageId messageId2 = producer.newMessage(Schema.INT32).property("INT", "Y").value(18).send();
    Assert.assertEquals(ackCallback.get(messageId2), Arrays.asList(interceptor1.tag, interceptor3.tag));
    log.info("Send result messageId: {}", messageId2);
    producer.close();
}

