    ConsumerInterceptor<String> interceptor = new ConsumerInterceptor<String>() {

        @Override
        public void close() {
            throw new AbstractMethodError();
        }

        @Override
        public Message<String> beforeConsume(Consumer<String> consumer, Message<String> message) {
