        }

        @Override
        public void onAcknowledgeCumulative(Consumer<String> consumer, MessageId messageId, Throwable exception) {
            throw new AbstractMethodError();
        }

        @Override
        public void onNegativeAcksSend(Consumer<String> consumer, Set<MessageId> messageIds) {
            throw new AbstractMethodError();
        }

        @Override
        public void onAckTimeoutSend(Consumer<String> consumer, Set<MessageId> messageIds) {
            throw new AbstractMethodError();
        }
    };
    Consumer<String> consumer1 = pulsarClient.newConsumer(Schema.STRING).topic("persistent://my-property/my-ns/my-topic-exception").subscriptionType(SubscriptionType.Shared).intercept(interceptor).subscriptionName("my-subscription-ack-timeout").ackTimeout(3, TimeUnit.SECONDS).subscribe();
    Consumer<String> consumer2 = pulsarClient.newConsumer(Schema.STRING).topic("persistent://my-property/my-ns/my-topic-exception").subscriptionType(SubscriptionType.Shared).intercept(interceptor).subscriptionName("my-subscription-negative").subscribe();
