@Test(timeOut = 30000)
public void testRoundRobinProducer() throws Exception {
    log.info("-- Starting {} test --", methodName);
    // Creates new client connection
    PulsarClient pulsarClient = newPulsarClient(lookupUrl.toString(), 0);
    int numPartitions = 4;
