    Consumer<byte[]> consumer1 = pulsarClient.newConsumer().topic("persistent://my-property/my-ns/my-topic2").subscriptionName("my-subscriber-name").subscriptionType(SubscriptionType.Shared).receiverQueueSize(5).priorityLevel(1).subscribe();
