    // Creates new client connection
    PulsarClient newPulsarClient1 = newPulsarClient(lookupUrl.toString(), 0);
    Consumer<byte[]> consumer3 = newPulsarClient1.newConsumer().topic("persistent://my-property/my-ns/my-topic2").subscriptionName("my-subscriber-name").subscriptionType(SubscriptionType.Shared).receiverQueueSize(5).priorityLevel(1).subscribe();
    // Creates new client connection
    PulsarClient newPulsarClient2 = newPulsarClient(lookupUrl.toString(), 0);
    Consumer<byte[]> consumer4 = newPulsarClient2.newConsumer().topic("persistent://my-property/my-ns/my-topic2").subscriptionName("my-subscriber-name").subscriptionType(SubscriptionType.Shared).receiverQueueSize(5).priorityLevel(2).subscribe();
    Producer<byte[]> producer = pulsarClient.newProducer().topic("persistent://my-property/my-ns/my-topic2").create();
    List<Future<MessageId>> futures = Lists.newArrayList();
    // Asynchronously produce messages
    for (int i = 0; i < 15; i++) {
        final String message = "my-message-" + i;
        Future<MessageId> future = producer.sendAsync(message.getBytes());
        futures.add(future);
    }
    log.info("Waiting for async publish to complete");
    for (Future<MessageId> future : futures) {
        future.get();
    }
    for (int i = 0; i < 20; i++) {
        consumer1.receive(100, TimeUnit.MILLISECONDS);
        consumer2.receive(100, TimeUnit.MILLISECONDS);
    }
    /**
     * a. consumer1 and consumer2 now has more permits (as received and sent more permits) b. try to produce more
     * messages: which will again distribute among consumer1 and consumer2 and should not dispatch to consumer4
     */
    for (int i = 0; i < 5; i++) {
        final String message = "my-message-" + i;
        Future<MessageId> future = producer.sendAsync(message.getBytes());
        futures.add(future);
    }
