    // Asynchronously acknowledge upto and including the last message
    producer.close();
    consumer1.close();
    consumer2.close();
    consumer3.close();
    consumer4.close();
    newPulsarClient.close();
    newPulsarClient1.close();
    newPulsarClient2.close();
    log.info("-- Exiting {} test --", methodName);
}

