    Consumer<byte[]> consumer1 = newPulsarClient.newConsumer().topic("persistent://my-property/use/my-ns/my-topic2").subscriptionName("my-subscriber-name").subscriptionType(SubscriptionType.Shared).priorityLevel(1).receiverQueueSize(5).subscribe();
