    assertTrue(ownershipCache.getOwnedBundles().keySet().isEmpty());
    // Strategical retry
    retryStrategically((test) -> (producer1.getClientCnx() == null && consumer1.getClientCnx() == null && producer2.getClientCnx() == null), 5, 100);
