@Test
public void testAddEntryOperationTimeout() throws Exception {
    log.info("-- Starting {} test --", methodName);
    conf.setManagedLedgerAddEntryTimeoutSeconds(1);
    final String topicName = "persistent://my-property/my-ns/addEntryTimeoutTopic";
    Producer<byte[]> producer = pulsarClient.newProducer().topic(topicName).create();
    ConsumerImpl<byte[]> consumer = (ConsumerImpl<byte[]>) pulsarClient.newConsumer().topic(topicName).subscriptionName("my-subscriber-name").subscribe();
    PersistentTopic topic = (PersistentTopic) pulsar.getBrokerService().getOrCreateTopic(topicName).get();
    ManagedLedgerImpl ml = (ManagedLedgerImpl) topic.getManagedLedger();
    class MockLedgerHandle extends PulsarMockLedgerHandle {

        public MockLedgerHandle(PulsarMockBookKeeper bk, long id, DigestType digest, byte[] passwd) throws GeneralSecurityException {
            super(bk, id, digest, passwd);
        }

        @Override
        public void asyncAddEntry(final byte[] data, final AddCallback cb, final Object ctx) {
            // do nothing
        }

        @Override
        public void asyncClose(org.apache.bookkeeper.client.AsyncCallback.CloseCallback cb, Object ctx) {
            cb.closeComplete(BKException.Code.OK, this, ctx);
        }
    }
    MockLedgerHandle ledgerHandle = mock(MockLedgerHandle.class);
    final byte[] data = "data".getBytes();
    // this will make first entry to be timed out but then managed-ledger will create a new ledger and next time add
    // entry should be successful.
    doNothing().when(ledgerHandle).asyncAddEntry(data, null, null);
    MockedPulsarServiceBaseTest.setFieldValue(ManagedLedgerImpl.class, ml, "currentLedger", ledgerHandle);
    CountDownLatch latch = new CountDownLatch(1);
    AtomicBoolean addedSuccessfully = new AtomicBoolean(false);
    producer.sendAsync(data).handle((res, ex) -> {
        if (ex == null) {
            addedSuccessfully.set(true);
        } else {
            log.error("add-entry failed for {}", methodName, ex);
        }
        latch.countDown();
        return null;
    });
    latch.await();
    // broker should be resilient enough to add-entry timeout and add entry successfully.
    assertTrue(addedSuccessfully.get());
    byte[] receivedData = consumer.receive().getData();
    assertEquals(receivedData, data);
    producer.close();
    consumer.close();
}

@Test
public void testCompactedOutMessages() throws Exception {
    final String topic1 = "persistent://my-property/my-ns/my-topic";
    MessageMetadata metadata = MessageMetadata.newBuilder().setProducerName("foobar").setSequenceId(1).setPublishTime(1).setNumMessagesInBatch(3).build();
    // build a buffer with 4 messages, first and last compacted out
    ByteBuf batchBuffer = Unpooled.buffer(1000);
    Commands.serializeSingleMessageInBatchWithPayload(SingleMessageMetadata.newBuilder().setCompactedOut(true).setPartitionKey("key1"), Unpooled.EMPTY_BUFFER, batchBuffer);
    Commands.serializeSingleMessageInBatchWithPayload(SingleMessageMetadata.newBuilder().setCompactedOut(true).setPartitionKey("key2"), Unpooled.EMPTY_BUFFER, batchBuffer);
    Commands.serializeSingleMessageInBatchWithPayload(SingleMessageMetadata.newBuilder().setCompactedOut(false).setPartitionKey("key3"), Unpooled.EMPTY_BUFFER, batchBuffer);
    Commands.serializeSingleMessageInBatchWithPayload(SingleMessageMetadata.newBuilder().setCompactedOut(true).setPartitionKey("key4"), Unpooled.EMPTY_BUFFER, batchBuffer);
    try (ConsumerImpl<byte[]> consumer = (ConsumerImpl<byte[]>) pulsarClient.newConsumer().topic(topic1).subscriptionName("my-subscriber-name").subscribe()) {
        // shove it in the sideways
        consumer.receiveIndividualMessagesFromBatch(metadata, 0, batchBuffer, MessageIdData.newBuilder().setLedgerId(1234).setEntryId(567).build(), consumer.cnx());
        Message<?> m = consumer.receive();
        assertEquals(((BatchMessageIdImpl) m.getMessageId()).getLedgerId(), 1234);
        assertEquals(((BatchMessageIdImpl) m.getMessageId()).getEntryId(), 567);
        assertEquals(((BatchMessageIdImpl) m.getMessageId()).getBatchIndex(), 2);
        assertEquals(m.getKey(), "key3");
        assertEquals(consumer.numMessagesInQueue(), 0);
    }
}

