@Test(dataProvider = "variations")
public void testNegativeAcks(boolean batching, boolean usePartitions, SubscriptionType subscriptionType, int negAcksDelayMillis, int ackTimeout) throws Exception {
    log.info("Test negative acks batching={} partitions={} subType={} negAckDelayMs={}", batching, usePartitions, subscriptionType, negAcksDelayMillis);
    String topic = "testNegativeAcks-" + System.nanoTime();
    @Cleanup
    Consumer<String> consumer = pulsarClient.newConsumer(Schema.STRING).topic(topic).subscriptionName("sub1").acknowledgmentGroupTime(0, TimeUnit.SECONDS).subscriptionType(subscriptionType).negativeAckRedeliveryDelay(negAcksDelayMillis, TimeUnit.MILLISECONDS).ackTimeout(ackTimeout, TimeUnit.MILLISECONDS).subscribe();
    @Cleanup
    Producer<String> producer = pulsarClient.newProducer(Schema.STRING).topic(topic).enableBatching(batching).create();
    Set<String> sentMessages = new HashSet<>();
    final int N = 10;
    for (int i = 0; i < N; i++) {
        String value = "test-" + i;
        producer.sendAsync(value);
        sentMessages.add(value);
    }
    producer.flush();
    for (int i = 0; i < N; i++) {
        Message<String> msg = consumer.receive();
        consumer.negativeAcknowledge(msg);
    }
    Set<String> receivedMessages = new HashSet<>();
    // All the messages should be received again
    for (int i = 0; i < N; i++) {
        Message<String> msg = consumer.receive();
        receivedMessages.add(msg.getValue());
        consumer.acknowledge(msg);
    }
    assertEquals(receivedMessages, sentMessages);
    // There should be no more messages
    assertNull(consumer.receive(100, TimeUnit.MILLISECONDS));
    consumer.close();
    producer.close();
}

