@Test
public void testCheckUnAcknowledgedMessageTimer() throws PulsarClientException, InterruptedException {
    String key = "testCheckUnAcknowledgedMessageTimer";
    final String topicName = "persistent://prop/ns-abc/topic-" + key;
    final String subscriptionName = "my-ex-subscription-" + key;
    final String messagePredicate = "my-message-" + key + "-";
    final int totalMessages = 3;
    // 1. producer connect
    Producer<byte[]> producer = pulsarClient.newProducer().topic(topicName).enableBatching(false).messageRoutingMode(MessageRoutingMode.SinglePartition).create();
    // 2. Create consumer
    ConsumerImpl<byte[]> consumer = (ConsumerImpl<byte[]>) pulsarClient.newConsumer().topic(topicName).subscriptionName(subscriptionName).receiverQueueSize(7).subscriptionType(SubscriptionType.Shared).ackTimeout(ackTimeOutMillis, TimeUnit.MILLISECONDS).subscribe();
    // 3. producer publish messages
    for (int i = 0; i < totalMessages; i++) {
        String message = messagePredicate + i;
        log.info("Producer produced: " + message);
        producer.send(message.getBytes());
    }
    Thread.sleep((long) (ackTimeOutMillis * 1.1));
    for (int i = 0; i < totalMessages; i++) {
        Message<byte[]> msg = consumer.receive();
        if (i != totalMessages - 1) {
            consumer.acknowledge(msg);
        }
    }
    assertEquals(consumer.getUnAckedMessageTracker().size(), 1);
    Message<byte[]> msg = consumer.receive();
    consumer.acknowledge(msg);
    assertEquals(consumer.getUnAckedMessageTracker().size(), 0);
    Thread.sleep((long) (ackTimeOutMillis * 1.1));
    assertEquals(consumer.getUnAckedMessageTracker().size(), 0);
}

