            return result.getParallelism() == 2 && result.getCleanupSubscription() == false;
        } catch (PulsarAdminException e) {
            return false;
        }
    }, 5, 150);
    assertFalse(admin.functions().getFunction(tenant, namespacePortion, functionName).getCleanupSubscription());
