    PulsarClientImpl client = mock(PulsarClientImpl.class);
    Timer timer = new HashedWheelTimer(new DefaultThreadFactory("pulsar-timer", Thread.currentThread().isDaemon()), 1, TimeUnit.MILLISECONDS);
    when(client.timer()).thenReturn(timer);
    ConsumerBase<byte[]> consumer = mock(ConsumerBase.class);
    doNothing().when(consumer).onAckTimeoutSend(any());
    doNothing().when(consumer).redeliverUnacknowledgedMessages(any());
    UnAckedMessageTracker tracker = new UnAckedMessageTracker(client, consumer, 1000000, 100000);
    tracker.close();
    assertTrue(tracker.isEmpty());
    assertEquals(tracker.size(), 0);
    MessageIdImpl mid = new MessageIdImpl(1L, 1L, -1);
    assertTrue(tracker.add(mid));
    assertFalse(tracker.add(mid));
    assertEquals(tracker.size(), 1);
    ConcurrentOpenHashSet<MessageId> headPartition = tracker.timePartitions.removeFirst();
    headPartition.clear();
    tracker.timePartitions.addLast(headPartition);
    assertFalse(tracker.add(mid));
    assertEquals(tracker.size(), 1);
    assertTrue(tracker.remove(mid));
    assertTrue(tracker.isEmpty());
    assertEquals(tracker.size(), 0);
    timer.stop();
}

@Test
public void testCache() {
    AtomicLong currentTime = new AtomicLong(0);
    Clock clock = mock(Clock.class);
    when(clock.millis()).then(invocation -> currentTime.longValue());
    AtomicInteger currentValue = new AtomicInteger(0);
    Supplier<Integer> cache = new ObjectCache<>(() -> currentValue.getAndIncrement(), 10, TimeUnit.MILLISECONDS, clock);
    cache.get();
    assertEquals(cache.get().intValue(), 0);
    assertEquals(cache.get().intValue(), 0);
    currentTime.set(1);
    // Still the value has not expired
    assertEquals(cache.get().intValue(), 0);
    currentTime.set(10);
    assertEquals(cache.get().intValue(), 1);
    currentTime.set(15);
    assertEquals(cache.get().intValue(), 1);
    currentTime.set(22);
    assertEquals(cache.get().intValue(), 2);
}

