    cmd.run(new String[] { "update", "--name", fnName, "--inputs", inputTopicName, "--output", outputTopicName, "--jar", url, "--tenant", "sample", "--namespace", "ns1", "--className", DummyFunction.class.getName(), "--disk", "8080808080808080", "--update-auth-data" });
