@Test
public void testInitialzation() throws MalformedURLException, InterruptedException, ExecutionException, PulsarAdminException {
    Properties properties = new Properties();
    properties.setProperty("serviceUrl", brokerUrl.toString());
    properties.setProperty("useTls", "false");
    String tenantName = UUID.randomUUID().toString();
    admin.tenants().createTenant(tenantName, new TenantInfo());
    String topicName = String.format("persistent://%s/ns/topic-scale-ns-0/topic", tenantName);
    int numberOfMessages = 10;
    ExecutorService executor = Executors.newSingleThreadExecutor();
    CompletableFuture<Void> future = new CompletableFuture<Void>();
    executor.execute(() -> {
        PulsarClientTool pulsarClientToolConsumer;
        try {
            pulsarClientToolConsumer = new PulsarClientTool(properties);
            String[] args = { "consume", "-t", "Exclusive", "-s", "sub-name", "-n", Integer.toString(numberOfMessages), "--hex", "-r", "30", topicName };
            Assert.assertEquals(pulsarClientToolConsumer.run(args), 0);
            future.complete(null);
        } catch (Throwable t) {
            future.completeExceptionally(t);
        }
    });
    // Make sure subscription has been created
    while (true) {
        try {
            List<String> subscriptions = admin.topics().getSubscriptions(topicName);
            if (subscriptions.size() == 1) {
                break;
            }
        } catch (Exception e) {
        }
        Thread.sleep(200);
    }
    PulsarClientTool pulsarClientToolProducer = new PulsarClientTool(properties);
    String[] args = { "produce", "--messages", "Have a nice day", "-n", Integer.toString(numberOfMessages), "-r", "20", "-p", "key1=value1", "-p", "key2=value2", "-k", "partition_key", topicName };
    Assert.assertEquals(pulsarClientToolProducer.run(args), 0);
    future.get();
    executor.shutdown();
}

@Test
public void testVersionStrings() throws Exception {
    // Fixable versions (those lacking a patch release) get normalized with a patch release of 0
    Assert.assertEquals(PulsarVersion.fixVersionString("1.2"), "1.2.0");
    Assert.assertEquals(PulsarVersion.fixVersionString("1.2-SNAPSHOT"), "1.2.0-SNAPSHOT");
    Assert.assertEquals(PulsarVersion.fixVersionString("1.2-SNAPSHOT+BUILD"), "1.2.0-SNAPSHOT+BUILD");
    Assert.assertEquals(PulsarVersion.fixVersionString("1.2+BUILD"), "1.2.0+BUILD");
    // Already valid versions get returned unchanged
    Assert.assertEquals(PulsarVersion.fixVersionString("1.2.3"), "1.2.3");
    Assert.assertEquals(PulsarVersion.fixVersionString("2.2.0"), "2.2.0");
    Assert.assertEquals(PulsarVersion.fixVersionString("3.0.0"), "3.0.0");
    Assert.assertEquals(PulsarVersion.fixVersionString("3.0.0-SNAPSHOT"), "3.0.0-SNAPSHOT");
    Assert.assertEquals(PulsarVersion.fixVersionString("1.2.3-SNAPSHOT"), "1.2.3-SNAPSHOT");
    Assert.assertEquals(PulsarVersion.fixVersionString("1.2.3-SNAPSHOT+BUILD"), "1.2.3-SNAPSHOT+BUILD");
    Assert.assertEquals(PulsarVersion.fixVersionString("1.2.3+BUILD"), "1.2.3+BUILD");
    // Non-fixable versions get returned as-is
    Assert.assertEquals(PulsarVersion.fixVersionString("1"), "1");
}

@Test
public void testChecksumSendCommand() throws Exception {
    // test checksum in send command
    String producerName = "prod-name";
    int sequenceId = 0;
    ByteBuf data = Unpooled.buffer(1024);
    MessageMetadata messageMetadata = MessageMetadata.newBuilder().setPublishTime(System.currentTimeMillis()).setProducerName(producerName).setSequenceId(sequenceId).build();
    int expectedChecksum = computeChecksum(messageMetadata, data);
    ByteBufPair clientCommand = Commands.newSend(1, 0, 1, ChecksumType.Crc32c, messageMetadata, data);
    clientCommand.retain();
    ByteBuf receivedBuf = ByteBufPair.coalesce(clientCommand);
    //skip [total-size]
    receivedBuf.skipBytes(4);
    int cmdSize = (int) receivedBuf.readUnsignedInt();
    receivedBuf.readerIndex(8 + cmdSize);
    int startMessagePos = receivedBuf.readerIndex();
    /**
     * 1. verify checksum and metadataParsing **
     */
    boolean hasChecksum = Commands.hasChecksum(receivedBuf);
    int checksum = Commands.readChecksum(receivedBuf);
    // verify checksum is present
    assertTrue(hasChecksum);
    // verify checksum value
    assertEquals(expectedChecksum, checksum);
    MessageMetadata metadata = Commands.parseMessageMetadata(receivedBuf);
    // verify metadata parsing
    assertEquals(metadata.getProducerName(), producerName);
    /**
     * 2. parseMessageMetadata should skip checksum if present *
     */
    receivedBuf.readerIndex(startMessagePos);
    metadata = Commands.parseMessageMetadata(receivedBuf);
    // verify metadata parsing
    assertEquals(metadata.getProducerName(), producerName);
}

@Test(dataProvider = "codec")
void testCompressDecompress(CompressionType type) throws IOException {
    CompressionCodec codec = CompressionCodecProvider.getCompressionCodec(type);
    byte[] data = text.getBytes();
    ByteBuf raw = PulsarByteBufAllocator.DEFAULT.directBuffer();
    raw.writeBytes(data);
    ByteBuf compressed = codec.encode(raw);
    assertEquals(raw.readableBytes(), data.length);
    int compressedSize = compressed.readableBytes();
    ByteBuf uncompressed = codec.decode(compressed, data.length);
    assertEquals(compressed.readableBytes(), compressedSize);
    assertEquals(uncompressed.readableBytes(), data.length);
    assertEquals(uncompressed, raw);
    raw.release();
    compressed.release();
    uncompressed.release();
    // Verify compression codecs have the same behavior with buffers ref counting
    assertEquals(raw.refCnt(), 0);
    assertEquals(compressed.refCnt(), 0);
    assertEquals(compressed.refCnt(), 0);
}

