        T(int value) {
            this.value = value;
        }

        @Override
        public int hashCode() {
            return Integer.hashCode(value);
        }

        @Override
        public boolean equals(Object obj) {
            if (obj instanceof T) {
                return value == ((T) obj).value;
            }
            return false;
        }
    }
    ConcurrentOpenHashMap<T, String> map = new ConcurrentOpenHashMap<>();
