    assertNotEquals(t2, t1_b);
    assertNull(map.put(t1, "t1"));
    assertEquals(map.get(t1), "t1");
    assertEquals(map.get(t1_b), "t1");
    assertNull(map.get(t2));
    assertEquals(map.remove(t1_b), "t1");
    assertNull(map.get(t1));
    assertNull(map.get(t1_b));
}

