@Test(timeOut = 10000)
public void blockingTake() throws Exception {
    BlockingQueue<Integer> queue = new GrowableArrayBlockingQueue<>();
    CountDownLatch latch = new CountDownLatch(1);
    new Thread(() -> {
        try {
            int expected = 0;
            for (int i = 0; i < 100; i++) {
                int n = queue.take();
                assertEquals(n, expected++);
            }
            latch.countDown();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }).start();
    int n = 0;
    for (int i = 0; i < 10; i++) {
        for (int j = 0; j < 10; j++) {
            queue.put(n);
            ++n;
        }
        // Wait until all the entries are consumed
        while (!queue.isEmpty()) {
            Thread.sleep(1);
        }
    }
    latch.await();
}

