@Test
public void testEventTimeBasedWindow() throws Exception {
    EvictionPolicy<Integer, ?> evictionPolicy = new WatermarkTimeEvictionPolicy<>(20);
    windowManager.setEvictionPolicy(evictionPolicy);
    TriggerPolicy<Integer, ?> triggerPolicy = new WatermarkTimeTriggerPolicy<Integer>(10, windowManager, evictionPolicy, windowManager);
    triggerPolicy.start();
    windowManager.setTriggerPolicy(triggerPolicy);
    windowManager.add(new EventImpl<>(1, 603, null));
    windowManager.add(new EventImpl<>(2, 605, null));
    windowManager.add(new EventImpl<>(3, 607, null));
    // This should trigger the scan to find
    // the next aligned window end ts, but not produce any activations
    windowManager.add(new WaterMarkEvent<Integer>(609));
    assertEquals(Collections.emptyList(), listener.allOnActivationEvents);
    windowManager.add(new EventImpl<>(4, 618, null));
    windowManager.add(new EventImpl<>(5, 626, null));
    windowManager.add(new EventImpl<>(6, 636, null));
    // send a watermark event, which should trigger three windows.
    windowManager.add(new WaterMarkEvent<Integer>(631));
    assertEquals(3, listener.allOnActivationEvents.size());
    assertEquals(Arrays.asList(new Event[] { new EventImpl<>(1, 603, null), new EventImpl<>(2, 605, null), new EventImpl<>(3, 607, null) }), listener.allOnActivationEvents.get(0));
    assertEquals(Arrays.asList(new Event[] { new EventImpl<>(1, 603, null), new EventImpl<>(2, 605, null), new EventImpl<>(3, 607, null), new EventImpl<>(4, 618, null) }), listener.allOnActivationEvents.get(1));
    assertEquals(Arrays.asList(new Event[] { new EventImpl<>(4, 618, null), new EventImpl<>(5, 626, null) }), listener.allOnActivationEvents.get(2));
    assertEquals(Collections.emptyList(), listener.allOnActivationExpiredEvents.get(0));
    assertEquals(Collections.emptyList(), listener.allOnActivationExpiredEvents.get(1));
    assertEquals(Arrays.asList(new Event[] { new EventImpl<>(1, 603, null), new EventImpl<>(2, 605, null), new EventImpl<>(3, 607, null) }), listener.allOnActivationExpiredEvents.get(2));
    assertEquals(Arrays.asList(new Event[] { new EventImpl<>(1, 603, null), new EventImpl<>(2, 605, null), new EventImpl<>(3, 607, null) }), listener.allOnActivationNewEvents.get(0));
    assertEquals(Arrays.asList(new Event[] { new EventImpl<>(4, 618, null) }), listener.allOnActivationNewEvents.get(1));
    assertEquals(Arrays.asList(new Event[] { new EventImpl<>(5, 626, null) }), listener.allOnActivationNewEvents.get(2));
    assertEquals(Arrays.asList(new Event[] { new EventImpl<>(1, 603, null), new EventImpl<>(2, 605, null), new EventImpl<>(3, 607, null) }), listener.allOnExpiryEvents.get(0));
    // add more events with a gap in ts
    windowManager.add(new EventImpl<>(7, 825, null));
    windowManager.add(new EventImpl<>(8, 826, null));
    windowManager.add(new EventImpl<>(9, 827, null));
    windowManager.add(new EventImpl<>(10, 839, null));
    listener.clear();
    windowManager.add(new WaterMarkEvent<Integer>(834));
    assertEquals(3, listener.allOnActivationEvents.size());
    assertEquals(Arrays.asList(new Event[] { new EventImpl<>(5, 626, null), new EventImpl<>(6, 636, null) }), listener.allOnActivationEvents.get(0));
    assertEquals(Arrays.asList(new Event[] { new EventImpl<>(6, 636, null) }), listener.allOnActivationEvents.get(1));
    assertEquals(Arrays.asList(new Event[] { new EventImpl<>(7, 825, null), new EventImpl<>(8, 826, null), new EventImpl<>(9, 827, null) }), listener.allOnActivationEvents.get(2));
    assertEquals(Arrays.asList(new Event[] { new EventImpl<>(4, 618, null) }), listener.allOnActivationExpiredEvents.get(0));
    assertEquals(Arrays.asList(new Event[] { new EventImpl<>(5, 626, null) }), listener.allOnActivationExpiredEvents.get(1));
    assertEquals(Collections.emptyList(), listener.allOnActivationExpiredEvents.get(2));
    assertEquals(Arrays.asList(new Event[] { new EventImpl<>(6, 636, null) }), listener.allOnActivationNewEvents.get(0));
    assertEquals(Collections.emptyList(), listener.allOnActivationNewEvents.get(1));
    assertEquals(Arrays.asList(new Event[] { new EventImpl<>(7, 825, null), new EventImpl<>(8, 826, null), new EventImpl<>(9, 827, null) }), listener.allOnActivationNewEvents.get(2));
    assertEquals(Arrays.asList(new Event[] { new EventImpl<>(4, 618, null) }), listener.allOnExpiryEvents.get(0));
    assertEquals(Arrays.asList(new Event[] { new EventImpl<>(5, 626, null) }), listener.allOnExpiryEvents.get(1));
    assertEquals(Arrays.asList(new Event[] { new EventImpl<>(6, 636, null) }), listener.allOnExpiryEvents.get(2));
}

