    assertEquals(Arrays.asList(new Event[] { new EventImpl<>(9, 665, null), new EventImpl<>(10, 666, null), new EventImpl<>(11, 667, null), new EventImpl<>(12, 669, null) }), listener.allOnActivationEvents.get(1));
