public void updateFunction() throws PulsarClientException {
    WorkerConfig workerConfig = new WorkerConfig();
    workerConfig.setWorkerId("worker-1");
    FunctionMetaDataManager functionMetaDataManager = spy(new FunctionMetaDataManager(workerConfig, mock(SchedulerManager.class), mockPulsarClient()));
    Function.FunctionMetaData m1 = Function.FunctionMetaData.newBuilder().setFunctionDetails(Function.FunctionDetails.newBuilder().setName("func-1")).build();
