    when(mockedManager.getFunctionMetaData(eq(tenant), eq(namespace), eq(sink))).thenReturn(metaData);
    getDefaultSinkInfo();
    assertEquals(SinkConfigUtils.convertFromDetails(functionDetails), getDefaultSinkInfo());
