    genericAvroSchema = new GenericAvroSchema(schema.getSchemaInfo());
    when(message.getValue()).thenReturn(genericAvroSchema.decode(bytes));
    log.info("cpu:{}, Message.getValue: {}, record.getValue: {}", cpu.toString(), message.getValue().toString(), record.getValue().toString());
    influxSink.open(configMap, mockSinkContext);
    verify(this.influxDB, times(1)).describeDatabases();
