    // prepare a foo Record
    Foo obj = new Foo();
    obj.setField1("FakeFiled1");
    obj.setField2("FakeFiled1");
    AvroSchema<Foo> schema = AvroSchema.of(Foo.class);
    byte[] bytes = schema.encode(obj);
    AutoConsumeSchema autoConsumeSchema = new AutoConsumeSchema();
    autoConsumeSchema.setSchema(GenericSchemaImpl.of(schema.getSchemaInfo()));
    Record<GenericRecord> record = PulsarRecord.<GenericRecord>builder().message(message).topicName("fake_topic_name").build();
    genericAvroSchema = new GenericAvroSchema(schema.getSchemaInfo());
    when(message.getValue()).thenReturn(genericAvroSchema.decode(bytes));
    log.info("foo:{}, Message.getValue: {}, record.getValue: {}", obj.toString(), message.getValue().toString(), record.getValue().toString());
