@Test
public void testStreaming() throws Exception {
    LinkedBlockingQueue<String> dataQueue = new LinkedBlockingQueue<>();
    Server streamingServer = new Server(0);
    streamingServer.setHandler(newStreamingHandler(dataQueue));
    streamingServer.start();
    Properties props = new Properties();
    props.setProperty("httpOutputBufferSize", "1");
    props.setProperty("httpReverseProxy.foobar.path", "/stream");
    props.setProperty("httpReverseProxy.foobar.proxyTo", streamingServer.getURI().toString());
    props.setProperty("servicePort", "0");
    props.setProperty("webServicePort", "0");
    ProxyConfiguration proxyConfig = PulsarConfigurationLoader.create(props, ProxyConfiguration.class);
    AuthenticationService authService = new AuthenticationService(PulsarConfigurationLoader.convertFrom(proxyConfig));
    WebServer webServer = new WebServer(proxyConfig, authService);
    ProxyServiceStarter.addWebServerHandlers(webServer, proxyConfig, new BrokerDiscoveryProvider(proxyConfig, mockZooKeeperClientFactory));
    webServer.start();
    HttpClient httpClient = new HttpClient();
    httpClient.start();
    try {
        LinkedBlockingQueue<Byte> responses = new LinkedBlockingQueue<>();
        CompletableFuture<Result> promise = new CompletableFuture<>();
        httpClient.newRequest(webServer.getServiceUri()).path("/stream").onResponseContent((response, content) -> {
            while (content.hasRemaining()) {
                try {
                    responses.put(content.get());
                } catch (Exception e) {
                    log.error("Error reading response", e);
                    promise.completeExceptionally(e);
                }
            }
        }).send((result) -> {
            log.info("Response complete");
            promise.complete(result);
        });
        dataQueue.put("Some data");
        assertEventuallyTrue(() -> responses.size() == "Some data".length());
        Assert.assertEquals("Some data", drainToString(responses));
        Assert.assertFalse(promise.isDone());
        dataQueue.put("More data");
        assertEventuallyTrue(() -> responses.size() == "More data".length());
        Assert.assertEquals("More data", drainToString(responses));
        Assert.assertFalse(promise.isDone());
        dataQueue.put("DONE");
        assertEventuallyTrue(() -> promise.isDone());
        Assert.assertTrue(promise.get().isSucceeded());
    } finally {
        webServer.stop();
        httpClient.stop();
        streamingServer.stop();
    }
}

@Test
public void testLookup() throws Exception {
    @Cleanup
    PulsarClient client = PulsarClient.builder().serviceUrl(proxyService.getServiceUrl()).connectionsPerBroker(5).ioThreads(5).operationTimeout(1000, TimeUnit.MILLISECONDS).build();
    assertTrue(proxyService.getLookupRequestSemaphore().tryAcquire());
    assertTrue(proxyService.getLookupRequestSemaphore().tryAcquire());
    @Cleanup
    Producer<byte[]> producer1 = client.newProducer(Schema.BYTES).topic("persistent://sample/test/local/producer-topic").create();
    assertTrue(proxyService.getLookupRequestSemaphore().tryAcquire());
    try {
        @Cleanup
        Producer<byte[]> producer2 = client.newProducer(Schema.BYTES).topic("persistent://sample/test/local/producer-topic").create();
        Assert.fail("Should have failed since can't acquire LookupRequestSemaphore");
    } catch (Exception ex) {
        // Ignore
    }
    Assert.assertEquals(LookupProxyHandler.rejectedPartitionsMetadataRequests.get(), 11.0d);
    proxyService.getLookupRequestSemaphore().release();
    try {
        @Cleanup
        Producer<byte[]> producer3 = client.newProducer(Schema.BYTES).topic("persistent://sample/test/local/producer-topic").create();
    } catch (Exception ex) {
        Assert.fail("Should not have failed since can acquire LookupRequestSemaphore");
    }
    Assert.assertEquals(LookupProxyHandler.rejectedPartitionsMetadataRequests.get(), 11.0d);
}

