@Test
public void testMetrics() throws Exception {
    bolt.resetMetrics();
    String msgContent = "hello world";
    Tuple tuple = getMockTuple(msgContent);
    for (int i = 0; i < 10; i++) {
        bolt.execute(tuple);
    }
    for (int i = 0; i < NO_OF_RETRIES; i++) {
        Thread.sleep(1000);
        if (mockCollector.getNumTuplesAcked() == 10) {
            break;
        }
    }
    @SuppressWarnings("rawtypes")
